def get_divisors(n):
    divs = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i > 1:
                divs.append(i)
            if i * i != n and n // i > 1:
                divs.append(n // i)
    return divs

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def get_prime_factors(x):
    factors = set()
    d = 2
    while d * d <= x:
        if x % d == 0:
            factors.add(d)
            while x % d == 0:
                x //= d
        d += 1
    if x > 1:
        factors.add(x)
    return factors

