        for a in A:
            for b in range(M):
                if b not in A:
                    reachable.add((a + b) % M)
    else:
        # For larger cases, use the structural property
        # r is reachable iff exists a in A such that (r-a) mod M not in A
        # r is unreachable iff for all a in A, (r-a) mod M in A

        # Check only likely candidates based on GCD structure of A
        if len(A) <= 50:
            # Small A, can use direct check
            is_a_list = [False] * M
            for a in A:
                is_a_list[a] = True

            for r in range(M):
                possible = False
                for a in A:
                    if not is_a_list[(r - a) % M]:
                        possible = True
                        break
                if possible:
                    reachable.add(r)
        else:
            # Large N: compute reachable sums directly but efficiently
            is_a_list = [False] * M
            for a in A:
                is_a_list[a] = True

            for a in A:
                for b in range(M):
                    if not is_a[b]:
                        reachable.add((a + b) % M)

    # Find unreachable residues
    unreachable = sorted(range(M))
    unreachable = [r for r in unreachable if r not in reachable]

