from functools import lru_cache

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    strengths = list(map(int, lines[1].split()))
    m = int(lines[2])

    # Parse actions
    actions = []
    for i in range(m):
        parts = lines[3 + i].split()
        actions.append((parts[0], int(parts[1])))

    # Sort heroes in descending order by strength
    sorted_heroes = sorted(strengths, reverse=True)

    # Memoization cache
    @lru_cache(maxsize=None)
    def solve(action_idx, mask):
        """
        action_idx: current action number (0 to m)
        mask: bitmask where bit i is 1 if hero at sorted position i is used (picked or banned)
        Returns the final (Team1_strength - Team2_strength) when both play optimally
        """
        if action_idx >= m or mask == (1 << n) - 1:
            return 0  # No more actions

        action_type, team = actions[action_idx]

        # Find available heroes
        available = []
        for i in range(n):
            if not (mask & (1 << i)):  # bit not set means hero is still available
                available.append(i)

        if not available:
            return 0

        if action_type == 'p':
            # Pick action: team picks one hero from available
            # Team 1 adds to their score, Team 2 subtracts (wants to minimize difference)
            best = -float('inf')
            for idx in available:
                next_mask = mask | (1 << idx)  # mark as used
                point_value = sorted_heroes[idx]

                if team == 1:
                    # Team 1 wants to maximize difference
                    result = point_value + solve(action_idx + 1, next_mask)
                else:
                    # Team 2 wants to minimize difference (add negative of points)
                    result = -point_value + solve(action_idx + 1, next_mask)

                best = max(best, result)
            return best
        else:
            # Ban action: team removes one hero without getting any points
            # Team 1 wants to minimize (denies opponent) -> minimax
            # Team 2 wants to maximize (denies opponent) -> minimax from their perspective
            best = float('inf')
            for idx in available:
                next_mask = mask | (1 << idx)  # mark as used
                # Neither team gains points from banning, but they deny the future

                if team == 1:
                    # Team 1 plays minimax
                    result = solve(action_idx + 1, next_mask)
                else:
                    # Team 2 plays minimax
                    result = solve(action_idx + 1, next_mask)

                best = min(best, result)
            return best

    full_mask = 0
    result = solve(0, full_mask)
    return str(result)
