        if idx >= len(lines):
            break

        n = int(lines[idx])
        idx += 1

        nodes = []
        for i in range(n):
            parts = list(map(int, lines[idx].split()))
            idx += 1
            if parts[0] == -1:
                nodes.append({'type': 'node', 'l': parts[1], 'r': parts[2]})
            else:
                nodes.append({'type': 'leaf', 'val': parts[0]})

        # Calculate leaf counts for each subtree
        def count_leaves(u):
            if nodes[u]['type'] == 'leaf':
                return 1
            else:
                return count_leaves(nodes[u]['l']) + count_leaves(nodes[u]['r'])

        leaf_counts = {u: count_leaves(u) for u in range(n)}

        # Calculate value using minimax game theory
        def compute_value(u):
            if nodes[u]['type'] == 'leaf':
                return nodes[u]['val']
            else:
                left_val = compute_value(nodes[u]['l'])
                right_val = compute_value(nodes[u]['r'])

                # Number of moves needed to reduce this subtree to one value
                moves_at_u = leaf_counts[u] - 1

                # If odd moves, Pieguy (maximizer) gets the final decision at this node
                # If even moves, Piegirl (minimizer) gets the final decision at this node
                if moves_at_u % 2 == 1:
                    return max(left_val, right_val)
                else:
                    return min(left_val, right_val)

        result = compute_value(0)
        results.append(str(result))

    return '\n'.join(results)
