Looking at this problem, I need to solve a CNF satisfiability problem where each variable appears in at most 2 clauses. This is a variation of 2-SAT that can be solved using implication graphs and SCC decomposition.

The key insight is that for a CNF formula, a clause `(l1 OR l2 OR ... OR lk)` is equivalent to multiple implications:
- `¬l1 → l2`, `¬l1 → l3`, ..., `¬l1 → lk`
- `¬l2 → l1`, `¬l2 → l3`, ..., `¬l2 → lk`
- etc.

The standard 2-SAT approach using implication graphs will work here.

```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    def get_node(l):
        # l > 0 means x_l, l < 0 means ¬x_|l|
        # Node for x_i (i starting from 1): 2*(i-1)
        # Node for ¬x_i: 2*(i-1) + 1
        if l > 0:
            return 2 * (l - 1)
        else:
            return 2 * (abs(l) - 1) + 1

    total_nodes = 2 * m
    graph = [[] for _ in range(total_nodes)]
    reverse_graph = [[] for _ in range(total_nodes)]

    # Build implication graph from each clause
    # A clause (l1 OR l2 OR ... OR lk) gives implications: ¬li → lj for all j != i
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        k = parts[0]
        literals = parts[1:]

        # From each literal, negated implies all other literals
        for j in range(k):
            for p in range(k):
                if j != p:
                    li = literals[j]
                    lp = literals[p]
                    # ¬li → lp
                    u = get_node(-li)
                    v = get_node(lp)
                    graph[u].append(v)
                    reverse_graph[v].append(u)

    # First DFS for finishing order
    visited = [False] * total_nodes
    finish_order = []

    def dfs1(u):
        visited[u] = True
        for v in graph[u]:
            if not visited[v]:
                dfs1(v)
        finish_order.append(u)

    for i in range(total_nodes):
        if not visited[i]:
            dfs1(i)

    # Second DFS on reverse graph to find SCCs
    visited = [False] * total_nodes
    scc = [-1] * total_nodes
    scc_id = 0

    def dfs2(u):
        visited[u] = True
        scc[u] = scc_id
        for v in reverse_graph[u]:
            if not visited[v]:
                dfs2(v)

    for i in range(len(finish_order) - 1, -1, -1):
        u = finish_order[i]
        if not visited[u]:
            dfs2(u)
            scc_id += 1

    # Check for unsatisfiability
    # If x and ¬x are in the same SCC, unsatisfiable
    for i in range(m):
        pos = 2 * i
        neg = 2 * i + 1
        if scc[pos] == scc[neg]:
            return "NO"

    # Build assignment using topological ordering of SCCs
    # If SCC(pos) > SCC(neg), set x = 0 (¬x = True), else x = 1 (x = True)
    assignment = []
    for i in range(m):
        pos = 2 * i
        neg = 2 * i + 1
        if scc[pos] > scc[neg]:
            assignment.append(1)  # ¬xi can be false → xi is true (but based on SCC ordering)
        else:
            assignment.append(0)

    return "YES\n" + "".join(map(str, assignment))
