Looking at this problem, I need to:

1. Parse the input matrix
2. Check all possible submatrices (top-left, bottom-right coordinates)
3. For each submatrix, verify that:
   - Each row can form a palindrome (at most 1 character with odd count)
   - Each column can form a palindrome (at most 1 character with odd count)
   - These can be arranged simultaneously

The key insight is that we check row-wise palindrome validity AND column-wise palindrome validity for each submatrix. If both conditions are satisfied for all rows and columns in the submatrix, it's beautiful.

```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0\n'

    n, m = map(int, lines[0].split())
    matrix = [list(lines[i]) for i in range(1, n + 1)]

    def can_form_palindrome(counts):
        """Check if characters with a frequency distribution can form a palindrome"""
        odd_count = 0
        for c in counts:
            if c % 2 == 1:
                odd_count += 1
                if odd_count > 1:
                    return False
        return True

    ans = 0

    # Try all possible submatrices
    for r1 in range(n):
        for r2 in range(r1, n):
            for c1 in range(m):
                for c2 in range(c1, m):
                    # Check if all rows in submatrix can form palindromes
                    all_rows_ok = True
                    for r in range(r1, r2 + 1):
                        row_counts = [0] * 26
                        for c in range(c1, c2 + 1):
                            char_idx = ord(matrix[r][c]) - ord('a')
                            row_counts[char_idx] += 1
                        if not can_form_palindrome(row_counts):
                            all_rows_ok = False
                            break

                    if not all_rows_ok:
                        continue

                    # Check if all columns in submatrix can form palindromes
                    all_cols_ok = True
                    for c in range(c1, c2 + 1):
                        col_counts = [0] * 26
                        for r in range(r1, r2 + 1):
                            char_idx = ord(matrix[r][c]) - ord('a')
                            col_counts[char_idx] += 1
                        if not can_form_palindrome(col_counts):
                            all_cols_ok = False
                            break

                    if all_cols_ok:
                        ans += 1

    return str(ans) + '\n'
