    adj = [[] for _ in range(n + 1)]
    for line in lines[1:]:
        if not line.strip():
            continue
        u, v = map(int, line.split())
        adj[u].append(v)

    # BFS from each node to compute all-pairs shortest paths
    dist = [[float('inf')] * (n + 1) for _ in range(n + 1)]

    for start in range(1, n + 1):
        dist[start][start] = 0
        queue = [start]
        idx = 0
        while idx < len(queue):
            u = queue[idx]
            idx += 1
            for v in adj[u]:
                if dist[start][v] == float('inf'):
                    dist[start][v] = dist[start][u] + 1
                    queue.append(v)

    # Precompute best[i] = node that maximizes dist[node][i] for node != i
    # and sec_best[i] = second-best (for distinctness)
    best_pre = [[-1, -1, -1] for _ in range(n + 1)]

    for target in range(1, n + 1):
        candidates = []
        for node in range(1, n + 1):
            if node != target and dist[node][target] != float('inf'):
                d = dist[node][target]
                candidates.append((d, node))

        candidates.sort(reverse=True)
        # Store top 3 to handle distinctness constraints
        for idx, (d, node) in enumerate(candidates[:3]):
            best_pre[target][idx] = node

    # Precompute best_l[j] = node that maximizes dist[j][node] for node != j
    best_from = [[-1, -1, -1] for _ in range(n + 1)]

    for source in range(1, n + 1):
        candidates = []
