            if node != source and dist[source][node] != float('inf'):
                d = dist[source][node]
                candidates.append((d, node))

        candidates.sort(reverse=True)
        for idx, (d, node) in enumerate(candidates[:3]):
            best_from[source][idx] = node

    max_total = -1
    result = []

    # Precompute valid j, k pairs with accessible ranges
    for j in range(1, n + 1):
        for k in range(1, n + 1):
            if j == k:
                continue
            if dist[j][k] == float('inf'):
                continue

            # Pre-calculate best candidates for i and l
            # i from best_pre[j], l from best_from[k]

            best_i_list = [best_pre[j][0], best_pre[j][1], best_pre[j][2]]
            best_l_list = [best_from[k][0], best_from[k][1], best_from[k][2]]

            # Try to find valid combination
            found = False
            for i_idx in range(min(3, len(best_i_list))):
                i = best_i_list[i_idx]
                if i == -1:
                    continue
                if i == j or i == k:
                    continue

                for l_idx in range(min(3, len(best_l_list))):
                    l = best_l_list[l_idx]
                    if l == -1:
                        continue
                    if l == j or l == k or l == i:
                        continue

                    # Found valid distinct i, j, k, l
                    total = dist[i][j] + dist[j][k] + dist[k][l]
                    if total > max_total:
                        max_total = total
                        result = [i, j, k, l]
                    found = True
                    break
                if found:
                    break

            # If j, k pair doesn't work but all top candidates used, skip
            if not found:
                # Try second pass - this shouldn't happen with top 3
                for i_idx in range(3):
                    i = best_i_list[i_idx]
                    if i == -1:
