Looking at this problem, I need to color a grid graph where vertices are connected to all their 8 neighbors (king's moves in chess). The pattern must use 4 colors such that no two adjacent (including diagonal) vertices have the same color.

The key insight is that for a king's graph, a valid 4-coloring can be achieved using a repeating 2×2 pattern. Each position in the 2×2 block (defined by the parity of row and column indices) gets assigned a different color. There are 4! = 24 such patterns to try.

```python
from itertools import permutations

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = lines[1:n+1]

    original = []
    for i in range(n):
        original.append(list(grid[i]))

    # Check for immediate contradictions in pre-colored cells
    for i in range(n):
        for j in range(m):
            if original[i][j] != '0':
                c = int(original[i][j])
                for di in (-1, 0, 1):
                    for dj in (-1, 0, 1):
                        if di == 0 and dj == 0:
                            continue
                        ni, nj = i + di, j + dj
                        if 0 <= ni < n and 0 <= nj < m and original[ni][nj] != '0':
                            if int(original[ni][nj]) == c:
                                return "0"

    # Try all 24 permutations of the 2x2 pattern
    for perm in permutations([1, 2, 3, 4]):
        # perm[0] for (even, even), perm[1] for (odd, even), 
        # perm[2] for (even, odd), perm[3] for (odd, odd)
        perm_map = [
            perm[0],  # (even, even)
            perm[1],  # (odd, even)
            perm[2],  # (even, odd)
            perm[3],  # (odd, odd)
        ]

        valid = True
        for i in range(n):
            for j in range(m):
                if original[i][j] != '0':
                    ri, rj = i % 2, j % 2
                    idx = ri * 2 + rj
                    if int(original[i][j]) != perm_map[idx]:
                        valid = False
                        break
            if not valid:
                break

        if valid:
            result = []
            for i in range(n):
                row = []
                for j in range(m):
                    ri, rj = i % 2, j % 2
                    idx = ri * 2 + rj
                    row.append(str(perm_map[idx]))
                result.append("".join(row))
            return '\n'.join(result)

    return "0"
