def solution(input_str):
    lines = input_str.strip().split('\n')
    N = int(lines[0])

    adj = [[] for _ in range(N)]
    for i in range(1, len(lines)):
        if lines[i]:
            parts = list(map(int, lines[i].split()))
            u, v = parts[0], parts[1]
            adj[u].append(v)
            adj[v].append(u)

    def get_potential(node, started_nodes):
        queue = [node]
        component = {node}
        idx = 0
        while idx < len(queue):
            curr = queue[idx]
            idx += 1
            for dest in adj[curr]:
                if dest not in started_nodes and dest not in component:
                    component.add(dest)
                    queue.append(dest)
        return len(component)

    max_sum = 0

    def dfs(started_nodes, current_sum, kick_used):
        nonlocal max_sum
        if len(started_nodes) == N:
            max_sum = max(max_sum, current_sum)
            return

        available = []
        for node in range(N):
            if node not in started_nodes:
                if not kick_used:
                    available.append(node)
                else:
                    for neighbor in adj[node]:
                        if neighbor in started_nodes:
                            available.append(node)
                            break

        for i, node in enumerate(available):
            next_started = started_nodes | {node}
            pot = get_potential(node, next_started)
            dfs(next_started, current_sum + pot, True)

    if N > 0:
        for node in range(N):
            dfs({node}, 0, True)

    return str(max_sum)
