        attempts.append([int(ch) for ch in parts[0]])
        responses.append(int(parts[1]))

    # Meet-in-the-middle approach
    mid = n // 2

    # Precompute match counts for left half (positions 0 to mid-1)
    left_matches = [[0] * m for _ in range(1 << mid)]
    for mask in range(1 << mid):
        for i in range(m):
            matches = 0
            for j in range(mid):
                if ((mask >> j) & 1) == attempts[i][j]:
                    matches += 1
            left_matches[mask][i] = matches

    # Group left masks by their match pattern
    from collections import defaultdict
    left_by_pattern = defaultdict(list)
    for mask in range(1 << mid):
        pattern = tuple(left_matches[mask])
        left_by_pattern[pattern].append(mask)

    # Precompute match counts for right half (positions mid to n-1)
    right_matches = []
    for mask in range(1 << (n - mid)):
        match_counts = []
        for i in range(m):
            matches = 0
            for j in range(n - mid):
                if ((mask >> j) & 1) == attempts[i][mid + j]:
                    matches += 1
            match_counts.append(matches)
        right_matches.append(tuple(match_counts))

    # Group right patterns
    right_by_pattern = defaultdict(list)
    for mask, pattern in enumerate(right_matches):
        right_by_pattern[pattern].append(mask)

    # Combine and count valid pairs
    count = 0
    for left_pattern, left_masks in left_by_pattern.items():
        for right_pattern, right_masks in right_by_pattern.items():
            # Check if combined matches all responses
            combined = tuple(l + r for l, r in zip(left_pattern, right_pattern))
            if combined == tuple(responses):
                count += len(left_masks) * len(right_masks)

