        matrix = []
        for _ in range(n):
            matrix.append(list(map(int, lines[idx].split())))
            idx += 1

        ops = lines[idx]
        idx += 1

        for op in ops:
            if op == 'R':
                for i in range(n):
                    new_row = [matrix[i][(j - 1) % n] for j in range(n)]
                    matrix[i] = new_row
            elif op == 'L':
                for i in range(n):
                    new_row = [matrix[i][(j + 1) % n] for j in range(n)]
                    matrix[i] = new_row
            elif op == 'D':
                new_matrix = [row[:] for row in matrix]
                for j in range(n):
                    for i in range(n):
                        new_matrix[(i + 1) % n][j] = matrix[i][j]
                matrix = new_matrix
            elif op == 'U':
                new_matrix = [row[:] for row in matrix]
                for j in range(n):
                    for i in range(n):
                        new_matrix[i][j] = matrix[(i + 1) % n][j]
                matrix = new_matrix
            elif op == 'I':
                for i in range(n):
                    row = matrix[i]
                    pos = {v + 1: j for j, v in enumerate(row)}  # value -> position (0-indexed)
                    inv = []
                    for k in range(n):
                        inv.append(pos[k + 1])
                    matrix[i] = [x + 1 for x in inv]
            elif op == 'C':
                col_inv = [0] * n
                first = matrix[0]
                first_pos = {v + 1: i for i, v in enumerate(first)}

                new_matrix = [row[:] for row in matrix]
                for j in range(n):
                    col = [matrix[i][j] for i in range(n)]
                    col_pos = {v + 1: i for i, v in enumerate(col)}
                    for i in range(n):
                        new_matrix[i][j] = col_pos[matrix[i][j]] + 1
                matrix = new_matrix

        for row in matrix:
            result_lines.append(' '.join(map(str, row)))

    return '\n'.join(result_lines)

