                    if rem_a == 0 and rem_b == 0:
                        found = sets[:]
                        return
                    return

                # Try Team A wins
                for sa, sb in a_win_sets:
                    if rem_a >= sa and rem_b >= sb:
                        sets.append((sa, sb))
                        if search(idx + 1, rem_a - sa, rem_b - sb, sets, a_win_count + 1):
                            return
                        sets.pop()

                # Try Team B wins
                for sa, sb in b_win_sets:
                    if rem_a >= sa and rem_b >= sb:
                        sets.append((sa, sb))
                        if search(idx + 1, rem_a - sa, rem_b - sb, sets, a_win_count):
                            return
                        sets.pop()

            search(0, a_total, b_total, [], 0)

            if found:
                return (f"{a_score}:{b_score}", " ".join(f"{a}:{b}" for a, b in found))

        return (None, None)

    for i in range(1, m + 1):
        if i < len(lines):
            parts = lines[i].split()
            if len(parts) >= 2:
                a, b = int(parts[0]), int(parts[1])
                score, sets = find_best_score(a, b)
                if score is None:
                    output.append("Impossible")
                else:
                    output.append(score)
                    output.append(sets)

    return '\n'.join(output + [''])
