        # Pattern: 2*floor((n-1)/2)
        return str(2 * ((n - 1) // 2))

    if n == 2:
        # 2 rows, need pairs with distance 3 including vertical component
        if m % 2 == 0:
            # even columns, can fully pair up
            return str(m * 2)
        else:
            return str((m - 1) * 2)

    if n == 3:
        # 3 rows, special case
