            total = 3 * m
            if total % 2 == 0:
                return str(total - 1) if m <= 3 else str(total - 1)
            else:
                return str(total - 1)

    # For n >= 4 and m >= 4, we can almost always achieve full pairing
    # except when geometrically constrained
    total = n * m

    if total % 2 == 1:
        # odd total cells, one cell will be left unpaired due to coloring
        return str(total - 1)
    else:
        # even total cells, can achieve full pairing
        return str(total)
